// Package system assembles scaffolded integrations into a system host. It
// scans the workspace for the .intropy/scaffold.json records `int create`
// left behind, renders the system-host template with the template
// package's machinery, and generates the typed system declaration —
// Topics.cs and the ISystemDefinition class — from what the scaffolds
// recorded.
package system

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// hostTemplate is the directory in the templates repo holding the system
// host's shell and placeholders.
const hostTemplate = "system-host"

type CreateOptions struct {
	Name       string // system name as typed; PascalCase or kebab-case
	StartDir   string // workspace scan root; default "."
	OutputDir  string // default: the kebab-cased name
	Version    string // template release tag; default: latest
	Force      bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Test overrides. Production callers leave these zero-valued; the CLI
	// always targets the official template library.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// CreateResult is the machine-readable summary written when --output-json
// is set. Field names are stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`
	System    Summary        `json:"system"`
}

// Summary describes the assembled system; it loosely mirrors the model the
// host's `graph` verb prints.
type Summary struct {
	Name          string      `json:"name"`
	Components    []Component `json:"components"`
	Topics        []Topic     `json:"topics"`
	Connectors    []Connector `json:"connectors,omitempty"`
	SharedLibrary string      `json:"sharedLibrary"` // scaffold directory
}

func (o *CreateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full assembly: scan the workspace for scaffold records,
// validate them into a system model, render the system-host template, and
// generate the declaration files from the model. All local validation
// happens before any network I/O.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if opts.Name == "" {
		return fmt.Errorf("a system name is required")
	}

	// Exact parity with the templates' `{{ .name | kebabcase }}`: sprig
	// delegates to xstrings, so OrderFlow and order-flow are equivalent.
	kebab := xstrings.ToKebabCase(opts.Name)
	if opts.OutputDir == "" {
		opts.OutputDir = kebab
	}

	entries, warnings := template.ListScaffolds(opts.StartDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	warnf := func(format string, args ...any) {
		fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
	}
	model, err := Assemble(entries, warnf)
	if err != nil {
		return err
	}
	model.Name = kebab

	include, err := contractsInclude(opts.OutputDir, model.Shared)
	if err != nil {
		return err
	}

	if err := template.Create(ctx, template.CreateOptions{
		Template:      hostTemplate,
		OutputDir:     opts.OutputDir,
		Version:       opts.Version,
		SetValues:     map[string]any{"name": kebab},
		Force:         opts.Force,
		NoInput:       true, // the template's contract: only `name`, never prompt
		Stdin:         strings.NewReader(""),
		Stdout:        opts.Stdout,
		Stderr:        opts.Stderr,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		GitHubBaseURL: opts.GitHubBaseURL,
	}); err != nil {
		return err
	}

	// The template derives projectName/systemClass from the name; reading
	// them back from the record it just wrote makes CLI/template
	// derivation drift impossible.
	record, err := template.LoadScaffold(filepath.Join(opts.OutputDir, filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		return err
	}
	hostEntry := template.ScaffoldEntry{Path: opts.OutputDir, Scaffold: *record}
	if model.ProjectName, err = stringValue(hostEntry, "projectName"); err != nil {
		return fmt.Errorf("template %s did not derive the host project name: %w", hostTemplate, err)
	}
	if model.SystemClass, err = stringValue(hostEntry, "systemClass"); err != nil {
		return fmt.Errorf("template %s did not derive the system class name: %w", hostTemplate, err)
	}

	if err := writeTopicsFile(opts.OutputDir, model); err != nil {
		return err
	}
	withConnectors, err := writeConnectorsFile(opts.OutputDir, model, warnf)
	if err != nil {
		return err
	}
	if err := writeSystemClassFile(opts.OutputDir, model, withConnectors); err != nil {
		return err
	}
	if withConnectors {
		// The drop folders behind the default file transports, so an
		// extractor's first poll doesn't hit a missing directory.
		for _, c := range model.Connectors {
			if err := os.MkdirAll(filepath.Join(opts.OutputDir, "test", c.Name), 0o755); err != nil {
				return fmt.Errorf("create connector test folder: %w", err)
			}
		}
	}
	csproj := filepath.Join(opts.OutputDir, model.ProjectName+".SystemHost.csproj")
	if err := insertProjectReference(csproj, include); err != nil {
		return err
	}

	fmt.Fprintf(opts.Stderr, "assembled system %q: %d component(s), %d topic(s), %d connector(s), contracts from %s\n",
		model.Name, len(model.Components), len(model.Topics), len(model.Connectors), model.Shared.Path)

	return maybeWriteCreateResult(opts, record, model)
}

func maybeWriteCreateResult(opts CreateOptions, record *template.Scaffold, model *Model) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:  hostTemplate,
		Owner:     record.Owner,
		Repo:      record.Repo,
		Version:   record.Version,
		OutputDir: absOut,
		Values:    record.Values,
		System: Summary{
			Name:          model.Name,
			Components:    model.Components,
			Topics:        model.Topics,
			Connectors:    model.Connectors,
			SharedLibrary: model.Shared.Path,
		},
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output-json: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

package system

// TopicKey identifies a topic within the system: the pub/sub component it
// lives on plus the topic name. Two scaffolds naming the same key declare
// the two halves of one contract.
type TopicKey struct {
	Pubsub string `json:"pubsub"`
	Name   string `json:"topic"`
}

// Topic is one assembled topic: its key, the C# contract type its messages
// carry, and the identifier it gets in the generated Topics class.
type Topic struct {
	TopicKey
	Contract string `json:"contract"`
	Field    string `json:"-"`
}

// Component is one assembled system block.
type Component struct {
	AppID     string   `json:"name"` // the AddExtractor/AddLoader argument
	Kind      string   `json:"kind"` // template.BlockKindExtractor or BlockKindLoader
	Topic     TopicKey `json:"-"`
	Connector string   `json:"connector,omitempty"` // the From/To port; empty for records that predate it
	Path      string   `json:"path"`                // scaffold directory, for error messages
}

// Connector is one assembled connector: the named port an edge block reaches
// the outside world through, and the identifier it gets in the generated
// Connectors class. `sys create` resolves every connector to a local file
// transport rooted in the host's test/ folder.
type Connector struct {
	Name  string `json:"name"`
	Field string `json:"-"`
}

// SharedLibrary is the workspace's contract project: referenced by the
// host, never declared as a component.
type SharedLibrary struct {
	Path string // scaffold directory
	Name string // project name; also the namespace and csproj basename
}

// Model is the assembled system declaration `sys create` generates code
// from. Name, ProjectName and SystemClass are filled in around the
// template render; Assemble leaves them empty.
type Model struct {
	Name        string // kebab-case system name
	ProjectName string // template-derived PascalCase name
	SystemClass string // template-derived ISystemDefinition class name
	Components  []Component
	Topics      []Topic     // sorted by (Pubsub, Name)
	Connectors  []Connector // sorted by Name
	Shared      SharedLibrary
}

package system

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"text/template"

	intropytemplate "github.com/integrio-intropy/intropy-cli/internal/template"
)

// The generated declaration files. Deliberately namespace-less: the host
// project is small enough that the declaration reads as one document, and
// discovery reflects over the assembly regardless.
const topicsFileTmpl = `using Intropy.Topology;
using {{ .Shared.Name }};

/// <summary>The system's topics, each defined once and shared by every component that touches it.</summary>
public static class Topics
{
{{- range $i, $t := .Topics }}
{{- if $i }}
{{ end }}
    /// <summary>{{ $t.Contract }} messages on topic '{{ $t.Name }}' (pubsub '{{ $t.Pubsub }}').</summary>
    public static readonly TopicRef<{{ $t.Contract }}> {{ $t.Field }} = TopicRef<{{ $t.Contract }}>.Define("{{ $t.Pubsub }}", "{{ $t.Name }}");
{{- end }}
}
`

const connectorsFileTmpl = `using Intropy.Topology;

/// <summary>The system's connectors: the named ports its edge blocks reach the outside world through. Each defaults to a local file folder under test/ so the system runs with zero external configuration.</summary>
public static class Connectors
{
{{- range $i, $c := .Connectors }}
{{- if $i }}
{{ end }}
    /// <summary>Local file connector '{{ $c.Name }}' (folder ./test/{{ $c.Name }}). Point it at a real external system and transport when known.</summary>
    public static readonly ConnectorRef {{ $c.Field }} = ConnectorRef.Define("{{ $c.Name }}", Transport.File("./test/{{ $c.Name }}"));
{{- end }}
}
`

const systemClassFileTmpl = `using Intropy.Topology;

/// <summary>The {{ .Name }} system: what exists, and what connects it.</summary>
public sealed class {{ .SystemClass }} : ISystemDefinition
{
    public string SystemName => "{{ .Name }}";

    public void Define(SystemBuilder builder)
    {
{{- range .Components }}
        builder.{{ .Add }}("{{ .AppID }}")
{{- range .Calls }}
            {{ . }}
{{- end }};
{{- end }}
    }
}
`

// defaultExtractorSchedule is the cron every generated extractor starts with:
// once every minute. Extractors are run-to-completion jobs, so the host re-runs
// them on this schedule (CronJob emulation locally, a real CronJob in
// production). The generated file is the user's after `sys create` — edit the
// cron in place.
const defaultExtractorSchedule = "* * * * *"

var (
	topicsFile      = template.Must(template.New("Topics.cs").Parse(topicsFileTmpl))
	connectorsFile  = template.Must(template.New("Connectors.cs").Parse(connectorsFileTmpl))
	systemClassFile = template.Must(template.New("SystemClass.cs").Parse(systemClassFileTmpl))
)

// componentView is a Component with its builder call and chained wiring calls
// resolved for the system class template. Each call renders on its own line.
type componentView struct {
	AppID string
	Add   string   // AddExtractor | AddLoader
	Calls []string // the chained calls in order, e.g. `.From(...)`, `.Publishes(...)`, `.WithSchedule(...)`
}

// writeTopicsFile overwrites <dir>/Topics.cs with the assembled topic
// declarations.
func writeTopicsFile(dir string, m *Model) error {
	return renderTo(filepath.Join(dir, "Topics.cs"), topicsFile, m)
}

// writeConnectorsFile overwrites <dir>/Connectors.cs with the assembled
// connector declarations. Like the system class it refuses to create the
// file — but here a missing placeholder means the template release predates
// connectors (and its pinned Intropy.Topology has no Transport.File), so the
// system is generated without From/To instead of failing: it reports false
// and the caller degrades the system class the same way.
func writeConnectorsFile(dir string, m *Model, warnf func(format string, args ...any)) (bool, error) {
	path := filepath.Join(dir, "Connectors.cs")
	if _, err := os.Stat(path); err != nil {
		warnf("template rendered no Connectors.cs placeholder — this release predates connectors; generating the system without From/To (upgrade with --version <newer tag> to wire them)")
		return false, nil
	}
	return true, renderTo(path, connectorsFile, m)
}

// writeSystemClassFile overwrites <dir>/<SystemClass>.cs with the assembled
// system definition. It refuses to create the file: the rendered template
// must have left the placeholder, or its name derivation disagrees with
// this CLI and the write would add a second ISystemDefinition instead of
// replacing the placeholder. withConnectors=false (a template release that
// predates Connectors.cs) omits the From/To calls.
func writeSystemClassFile(dir string, m *Model, withConnectors bool) error {
	path := filepath.Join(dir, m.SystemClass+".cs")
	if _, err := os.Stat(path); err != nil {
		return fmt.Errorf("template rendered no %s.cs placeholder: the template's systemClass derivation disagrees with this CLI; upgrade intropy or pass --version <compatible tag>", m.SystemClass)
	}

	views := make([]componentView, len(m.Components))
	fieldByKey := map[TopicKey]string{}
	for _, t := range m.Topics {
		fieldByKey[t.TopicKey] = t.Field
	}
	connectorField := map[string]string{}
	for _, c := range m.Connectors {
		connectorField[c.Name] = c.Field
	}
	for i, c := range m.Components {
		v := componentView{AppID: c.AppID}
		topicField := fieldByKey[c.Topic]
		field, hasConnector := connectorField[c.Connector]
		hasConnector = hasConnector && withConnectors
		if c.Kind == intropytemplate.BlockKindExtractor {
			v.Add = "AddExtractor"
			if hasConnector {
				v.Calls = append(v.Calls, ".From(Connectors."+field+")")
			}
			v.Calls = append(v.Calls, ".Publishes(Topics."+topicField+")")
			// Gated on the same signal as From/To: a template release that
			// predates Connectors.cs also pins an Intropy.Topology without
			// WithSchedule, so the degraded shape must not call it.
			if withConnectors {
				v.Calls = append(v.Calls, `.WithSchedule("`+defaultExtractorSchedule+`")`)
			}
		} else {
			v.Add = "AddLoader"
			v.Calls = append(v.Calls, ".Subscribes(Topics."+topicField+")")
			if hasConnector {
				v.Calls = append(v.Calls, ".To(Connectors."+field+")")
			}
		}
		views[i] = v
	}

	return renderTo(path, systemClassFile, struct {
		Name        string
		SystemClass string
		Components  []componentView
	}{m.Name, m.SystemClass, views})
}

func renderTo(path string, tmpl *template.Template, data any) error {
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, data); err != nil {
		return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
	}
	if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
		return fmt.Errorf("generate %s: %w", filepath.Base(path), err)
	}
	return nil
}

// Package deploy generates Kubernetes deployment manifests (a kustomize
// base + overlays tree) for a previously scaffolded integration. It reads
// the committed .intropy/scaffold.json record, re-fetches the exact
// template version it pins, and renders the template's manifests/
// directory with the template package's template machinery.
package deploy

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

const (
	// manifestDirName is the directory inside a template (next to
	// skeleton/) that holds the deployment manifest template:
	// <template>/manifests/template.yaml + <template>/manifests/skeleton/.
	manifestDirName = "manifests"

	templateManifestName = "template.yaml"
	skeletonDirName      = "skeleton"

	// scaffoldValuesKey is the reserved key under which the full scaffold
	// value map is exposed to manifest templates ({{ .scaffold.name }}).
	scaffoldValuesKey = "scaffold"

	// defaultOutputDirName is the output directory relative to the project
	// root when --output is not given.
	defaultOutputDirName = "deploy"
)

type CreateOptions struct {
	StartDir   string // directory to begin the scaffold.json walk-up from; default "."
	OutputDir  string // default <projectRoot>/deploy
	Version    string // template release tag; default: the tag pinned in scaffold.json
	SetValues  map[string]any
	Files      []string
	Force      bool
	NoInput    bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdin      io.Reader
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Test overrides. Production callers leave these zero-valued; the
	// template is fetched from the owner/repo recorded in scaffold.json.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// CreateResult is the machine-readable summary written when --output-json is
// set. Field names are stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`
}

func (o *CreateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdin == nil {
		o.Stdin = os.Stdin
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create generates the deployment manifests: locate scaffold.json, download
// the pinned template, load manifests/template.yaml, resolve values (seeded
// from the scaffold record, with optional interactive prompting), render
// manifests/skeleton into the output directory.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()

	scaffold, projectRoot, err := template.FindScaffold(opts.StartDir)
	if err != nil {
		if errors.Is(err, template.ErrScaffoldNotFound) {
			return fmt.Errorf("%w\nThis project was scaffolded before deployment metadata existed. Re-scaffold it with 'intropy int create', or commit a minimal %s:\n  {\"schemaVersion\":1,\"template\":\"<template>\",\"owner\":\"integrio-intropy\",\"repo\":\"intropy-templates\",\"version\":\"<tag>\",\"values\":{\"name\":\"<name>\"}}", err, template.ScaffoldRelPath)
		}
		return err
	}
	if scaffold.SchemaVersion > template.ScaffoldSchemaVersion {
		return fmt.Errorf("%s has schemaVersion %d, but this CLI supports up to %d; upgrade intropy", template.ScaffoldRelPath, scaffold.SchemaVersion, template.ScaffoldSchemaVersion)
	}
	owner, repo := scaffold.Owner, scaffold.Repo
	if opts.Owner != "" {
		owner = opts.Owner
	}
	if opts.Repo != "" {
		repo = opts.Repo
	}

	tag := scaffold.Version
	if opts.Version != "" {
		tag = opts.Version
	}
	if tag == "" {
		return fmt.Errorf("%s does not pin a template version; pass --version", template.ScaffoldRelPath)
	}

	gh := template.NewGitHubClient(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
	fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", owner, repo, tag)
	templateRoot, cleanup, err := template.DownloadTemplate(ctx, gh, owner, repo, tag, scaffold.Template, "intropy-manifests-*")
	if err != nil {
		return err
	}
	defer cleanup()

	manifestsRoot := filepath.Join(templateRoot, manifestDirName)
	skelRoot := filepath.Join(manifestsRoot, skeletonDirName)
	if !dirExists(skelRoot) || !fileExists(filepath.Join(manifestsRoot, templateManifestName)) {
		return fmt.Errorf("template %q at %s does not include deployment manifest templates (%s/); pass --version <newer tag> or update the template", scaffold.Template, tag, manifestDirName)
	}

	tmpl, err := template.LoadTemplate(filepath.Join(manifestsRoot, templateManifestName))
	if err != nil {
		return err
	}
	values, err := resolveManifestValues(tmpl, scaffold, opts)
	if err != nil {
		return err
	}

	outputDir := opts.OutputDir
	if outputDir == "" {
		outputDir = filepath.Join(projectRoot, defaultOutputDirName)
	}
	if err := template.EnsureOutputDir(outputDir, opts.Force); err != nil {
		return err
	}
	if err := template.Render(skelRoot, outputDir, values); err != nil {
		return err
	}
	fmt.Fprintf(opts.Stderr, "wrote deployment manifests to %s (template %s@%s)\n", outputDir, scaffold.Template, tag)

	return maybeWriteCreateResult(opts, scaffold, owner, repo, tag, outputDir, values)
}

// resolveManifestValues resolves the manifest template's parameters, seeded
// by the scaffold record: scaffold values whose names match declared
// parameters auto-fill (no re-prompt) but yield to --values/--set. The full
// scaffold value map is exposed under the reserved "scaffold" key — added
// after Resolve so it never contaminates JSON Schema validation.
func resolveManifestValues(tmpl *template.Template, scaffold *template.Scaffold, opts CreateOptions) (map[string]any, error) {
	declared := map[string]bool{}
	for _, f := range tmpl.Fields() {
		if f.Name == scaffoldValuesKey {
			return nil, fmt.Errorf("manifest template declares reserved parameter %q", scaffoldValuesKey)
		}
		declared[f.Name] = true
	}
	if _, ok := tmpl.Spec.Values[scaffoldValuesKey]; ok {
		return nil, fmt.Errorf("manifest template declares reserved spec.values entry %q", scaffoldValuesKey)
	}

	seed := map[string]any{}
	for k, v := range scaffold.Values {
		if declared[k] {
			seed[k] = v
		}
	}

	prompter := template.AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
	values, err := template.ResolveLayered(tmpl, seed, opts.Files, opts.Stdin, opts.SetValues, prompter)
	if err != nil {
		return nil, err
	}
	values[scaffoldValuesKey] = scaffold.Values
	return values, nil
}

func maybeWriteCreateResult(opts CreateOptions, scaffold *template.Scaffold, owner, repo, tag, outputDir string, values map[string]any) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absOut, err := filepath.Abs(outputDir)
	if err != nil {
		absOut = outputDir
	}
	result := CreateResult{
		Template:  scaffold.Template,
		Owner:     owner,
		Repo:      repo,
		Version:   tag,
		OutputDir: absOut,
		Values:    values,
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output-json: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

func dirExists(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
